// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const slugify = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .slice(0, 60);

const img = (url: string, alt: string) => ({
  url,
  alt,
  publicId: "",
  width: 1200,
  height: 800,
  type: "image" as const,
});

const today = new Date();

function makeDepartures(startOffsetDays: number, count: number, gapDays = 14) {
  const deps: IPackage["departures"] = [];
  for (let i = 0; i < count; i++) {
    const date = new Date(today);
    date.setDate(date.getDate() + startOffsetDays + i * gapDays);
    const seatsTotal = 20;
    const seatsBooked = Math.floor(Math.random() * 14);
    deps.push({
      _id: "" as never,
      date,
      returnDate: new Date(date.getTime() + (i % 2 === 0 ? 7 : 5) * 86400000),
      departureCity: "Delhi",
      seatsTotal,
      seatsBooked,
      priceAdjustmentINR: i === 0 ? -2000 : 0,
      isFixedDeparture: true,
      isGuaranteed: i === 0,
      status: seatsBooked >= seatsTotal ? "sold_out" : seatsBooked >= seatsTotal - 3 ? "filling_fast" : "open",
    });
  }
  return deps;
}

