async function main() {
  await connectDB();

  // Upsert destinations
  for (const dest of destinations) {
    const existing = await Destination.findOne({ slug: dest.slug });
    if (existing) {
      await Destination.updateOne({ _id: existing._id }, { $set: dest });
      console.log(`  Updated destination: ${dest.name}`);
    } else {
      await Destination.create(dest as never);
      console.log(`  Created destination: ${dest.name}`);
    }
  }

  // Create collections if missing
  const collections: Omit<ICategory, "_id" | "createdAt" | "updatedAt">[] = [
    { name: "Trending International", slug: "trending-international", kind: "trip_type", order: 1 },
    { name: "Best of India", slug: "best-of-india", kind: "trip_type", order: 2 },
    { name: "Honeymoon Escapes", slug: "honeymoon-escapes", kind: "trip_type", order: 3 },
    { name: "Family Holidays", slug: "family-holidays", kind: "trip_type", order: 4 },
    { name: "Affordable Getaways", slug: "affordable-getaways", kind: "trip_type", order: 5 },
    { name: "Adventure Tours", slug: "adventure-tours", kind: "trip_type", order: 6 },
    { name: "Weekend Breaks", slug: "weekend-breaks", kind: "trip_type", order: 7 },
    { name: "Group Departures", slug: "group-departures", kind: "trip_type", order: 8 },
    { name: "Flight Inclusive", slug: "flight-inclusive", kind: "trip_type", order: 9 },
  ];

  for (const cat of collections) {
    const existing = await Category.findOne({ slug: cat.slug });
    if (!existing) {
      await Category.create(cat as never);
      console.log(`  Created collection: ${cat.name}`);
    }
  }

  // Upsert packages
  for (const pkg of packages) {
    const destSlug = (destinations.find((d) => d.name === pkg.citiesCovered[0])?.slug) || "";
    const destRecord = await Destination.findOne({ slug: destSlug });
    const resolvedDest = destRecord?._id || (await Destination.findOne({ name: pkg.citiesCovered[0] }))?._id;

    const existing = await Package.findOne({ slug: pkg.slug });
    const { destination: _omitDest, ...pkgWithoutDest } = pkg;
    const doc = {
      ...pkgWithoutDest,
      destination: resolvedDest!.toString(),
    } as Parameters<typeof Package.create>[0];

    if (existing) {
      await Package.updateOne({ _id: existing._id }, { $set: doc });
      console.log(`  Updated package: ${pkg.title}`);
    } else {
      await Package.create(doc);
      console.log(`  Created package: ${pkg.title}`);
    }
  }

  console.log(`\nDone — ${packages.length} demo packages processed.`);
  process.exit(0);
}

main().catch((err) => {
  console.error("Seed packages failed:", err);
  process.exit(1);
});
